# -*- coding: utf-8 -*-
from html import escape as e
from sample_identity import sample_label
from footer_designs import LAYOUTS, STYLE_LABELS, footer_options, render_footer

SPLIT_IDS={'company','cafe','beauty','academy','bakery','flower','cleaning','logistics','machinery','foodfactory'}

def render_picker(prefix,sample):
 sid=sample['id'];default=LAYOUTS[sid][0]
 options=footer_options().replace(f'value="{default}"',f'value="{default}" selected')
 picker=f'''<aside class="sample-tools" aria-label="샘플 도구"><button class="sample-tool sample-identity-tool" type="button" popovertarget="sample-info" aria-label="{e(sample_label(sample))} 정보" title="{e(sample_label(sample))}"><svg viewBox="0 0 24 24" aria-hidden="true"><rect width="18" height="18" x="3" y="3" rx="2"/><path d="M3 9h18M9 21V9"/></svg><span>{e(sample['sample_code'])}</span></button><button class="sample-tool" type="button" popovertarget="footer-options" aria-label="푸터 디자인 선택" title="푸터 디자인 선택"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="3"/><path d="M3 14h18M8 18h8"/></svg><span>푸터</span></button><button class="sample-tool" type="button" popovertarget="sample-menu" aria-label="샘플 메뉴 및 이용 안내" title="샘플 메뉴 및 이용 안내"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/></svg><span>메뉴</span></button><button class="sample-tool" type="button" data-inquiry="{sid}" aria-label="이 디자인으로 제작 상담" title="이 디자인으로 제작 상담"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-2 2v-6.5A8.5 8.5 0 1 1 20 11.5Z"/><path d="M7 8h8M7 12h5"/></svg><span>상담</span></button></aside>
<div class="sample-tool-panel" id="sample-info" popover="auto" aria-labelledby="sample-info-title"><div class="sample-tool-panel__head"><div><span class="sample-tool-panel__eyebrow">SAMPLE INFO</span><h2 id="sample-info-title">샘플 정보</h2></div><button class="sample-tool-close" type="button" popovertarget="sample-info" popovertargetaction="hide" aria-label="샘플 정보 닫기">×</button></div><div class="sample-info-details"><span class="sample-code">{e(sample['sample_code'])}</span><h3>{e(sample['design_name'])}</h3><p>{e(sample['category'])}</p></div></div>
<div class="sample-tool-panel" id="footer-options" popover="auto" aria-labelledby="footer-panel-title"><div class="sample-tool-panel__head"><div><span class="sample-tool-panel__eyebrow">FOOTER DESIGN</span><h2 id="footer-panel-title">푸터 디자인 선택</h2></div><button class="sample-tool-close" type="button" popovertarget="footer-options" popovertargetaction="hide" aria-label="푸터 선택 닫기">×</button></div><p class="sample-tool-context">본문: {e(sample_label(sample))}</p><div class="sample-tool-field"><label for="footer-style">푸터 스타일</label><select id="footer-style" aria-controls="sample-footer-slot">{options}</select></div><div class="sample-tool-links"><button type="button" id="reset-footer">추천 스타일로</button><a href="{prefix}footer-layouts.html?sample={sid}">{len(STYLE_LABELS)}가지 형태 비교</a></div><p id="footer-choice-status" role="status">{e(STYLE_LABELS[default])} 적용 중</p><button type="button" class="sample-tool-preview" id="view-selected-footer">적용한 푸터 보기</button></div>
<div class="sample-tool-panel" id="sample-menu" popover="auto" aria-labelledby="sample-menu-title"><div class="sample-tool-panel__head"><div><span class="sample-tool-panel__eyebrow">SAMPLE TOOLS</span><h2 id="sample-menu-title">샘플 메뉴</h2></div><button class="sample-tool-close" type="button" popovertarget="sample-menu" popovertargetaction="hide" aria-label="샘플 메뉴 닫기">×</button></div><p class="sample-tool-context">{e(sample_label(sample))}</p><nav class="sample-tool-nav" aria-label="샘플 및 이용 안내"><a href="{prefix}footer-layouts.html?sample={sid}">푸터 비교</a><a href="{prefix}credits.html">콘텐츠 출처</a><a href="{prefix}privacy.html">이용 안내</a><a href="#main" data-tool-top>맨 위로</a></nav></div>'''
 current=f'<div id="sample-footer-slot" data-default-footer="{default}" data-sample-id="{sid}">{render_footer(prefix,sample)}</div>'
 templates=''.join(f'<template data-footer-template="{key}">{render_footer(prefix,sample,key).replace(chr(32)+chr(105)+chr(100)+chr(61)+chr(34)+"footer"+chr(34),"")}</template>' for key in STYLE_LABELS)
 return picker+current+templates
